const cx = (...v: Array<string | false | undefined>) => v.filter(Boolean).join(" ");

function Button({ children, onClick, ghost = false, className = "" }: { children: ReactNode; onClick?: () => void; ghost?: boolean; className?: string }) {
  return <motion.button whileTap={{ scale: .97 }} whileHover={{ y: -1 }} onClick={onClick} className={cx("inline-flex h-9 items-center justify-center gap-2 rounded-[10px] px-4 text-xs font-semibold transition", ghost ? "border border-[#dcdffa] bg-white text-[#554bea] hover:bg-[#f5f4ff]" : "bg-gradient-to-r from-[#6258f5] to-[#4b40e8] text-white shadow-[0_7px_18px_rgba(98,88,245,.25)]", className)}>{children}</motion.button>;
}
function Card({ children, className = "", onClick }: { children: ReactNode; className?: string; onClick?: () => void }) {
  return <motion.section whileHover={onClick ? { y: -2 } : undefined} onClick={onClick} className={cx("rounded-[15px] border border-[#e8eaf5] bg-white p-4 shadow-[0_6px_22px_rgba(71,66,140,.055)]", onClick && "cursor-pointer", className)}>{children}</motion.section>;
}
function Title({ children, action }: { children: ReactNode; action?: ReactNode }) {
  return <div className="mb-4 flex items-center justify-between"><h3 className="border-l-[3px] border-[#6258f5] pl-2 text-[14px] font-bold">{children}</h3>{action}</div>;
}
function Pill({ children, green = false, orange = false }: { children: ReactNode; green?: boolean; orange?: boolean }) {
  return <span className={cx("inline-flex rounded-md px-2 py-1 text-[10px]", green ? "bg-emerald-50 text-emerald-600" : orange ? "bg-orange-50 text-orange-500" : "bg-[#f1efff] text-[#6258f5]")}>{children}</span>;
}
function Progress({ value, green = false }: { value: number; green?: boolean }) {
  return <div className="h-1.5 overflow-hidden rounded-full bg-[#eceef6]"><motion.div initial={{ width: 0 }} animate={{ width: `${value}%` }} className={cx("h-full rounded-full", green ? "bg-[#35ba88]" : "bg-gradient-to-r from-[#6258f5] to-[#8177ff]")} /></div>;
}
function Toggle({ checked, onClick }: { checked: boolean; onClick: () => void }) {
  return <button onClick={onClick} className={cx("relative h-5 w-9 rounded-full transition",checked?"bg-[#6258f5]":"bg-[#dfe1eb]")}><span className={cx("absolute top-0.5 size-4 rounded-full bg-white shadow transition",checked?"left-[18px]":"left-0.5")}/></button>;
}
function Avatar({ interviewer = false, className = "" }: { interviewer?: boolean; className?: string }) {
  return <div className={cx("relative", className)}><Image fill sizes="320px" className="object-contain" alt={interviewer ? "AI 面试官" : "职业数字分身"} src={`/assets/${interviewer ? "avatar-interviewer-suit.png" : "avatar-student-tablet.png"}`} /></div>;
}
function Metric({ label, value, note }: { label: string; value: string; note?: string }) {
  return <div className="rounded-xl bg-[#fafaff] p-3"><span className="text-[10px] text-[#8b91aa]">{label}</span><strong className="mt-1 block text-xl">{value}</strong>{note && <small className="text-[9px] text-[#9aa0b8]">{note}</small>}</div>;
}
function useMounted() {
  return useSyncExternalStore(()=>()=>{},()=>true,()=>false);
}
function RadarView({ compact = false }: { compact?: boolean }) {
  const mounted=useMounted();
  return <div className={cx("min-w-0",compact ? "h-44" : "h-60")}>{mounted?<ResponsiveContainer width="100%" height="100%" minWidth={0} minHeight={0}><RadarChart data={radar}><PolarGrid stroke="#e6e8f5"/><PolarAngleAxis dataKey="subject" tick={{ fontSize: 9, fill: "#69718d" }}/><Radar dataKey="old" stroke="#c5c8d9" fill="#c5c8d9" fillOpacity={.13}/><Radar dataKey="score" stroke="#6258f5" fill="#6258f5" fillOpacity={.28}/></RadarChart></ResponsiveContainer>:<div className="size-full rounded-xl bg-[#fafaff]"/>}</div>;
}
function TrendView() {
  const mounted=useMounted();
  return <div className="h-40 min-w-0">{mounted?<ResponsiveContainer width="100%" height="100%" minWidth={0} minHeight={0}><AreaChart data={trend}><defs><linearGradient id="v2trend" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#6258f5" stopOpacity=".25"/><stop offset="1" stopColor="#6258f5" stopOpacity="0"/></linearGradient></defs><CartesianGrid vertical={false} stroke="#f0f1f7"/><XAxis dataKey="d" tick={{ fontSize: 8 }} axisLine={false}/><YAxis hide/><Tooltip/><Area dataKey="v" stroke="#6258f5" strokeWidth={2} fill="url(#v2trend)"/></AreaChart></ResponsiveContainer>:<div className="size-full rounded-xl bg-[#fafaff]"/>}</div>;
}

