export function Mission({ go, grow, toast }: { go: (p: PageId) => void; grow: () => void; toast: (s:string)=>void }) {
  const [tasks,setTasks]=useState([true,true,false,false,false]); const [text,setText]=useState(""); const [score,setScore]=useState(92); const [next,setNext]=useState(false);
  const submit=()=>{setScore(95);grow();toast("复盘提交成功，成长值 +120")};
  return <div className="space-y-3"><Card className="relative min-h-[230px] overflow-hidden bg-[radial-gradient(circle_at_76%_42%,#e8e6ff,transparent_32%)]"><Pill>副本挑战 · 第1关</Pill><h1 className="mt-3 text-[28px] font-bold">AI 产品经理实战副本</h1><p className="mt-2 max-w-[570px] text-xs leading-6 text-[#7d849e]">在真实产品场景中完成从需求洞察到方案落地的完整项目，用 AI 助手提升产品思维与项目能力。</p><div className="mt-5 max-w-[500px] rounded-xl border border-[#e5e5f5] bg-white/85 p-3 text-[10px]"><b>导师提示：</b>这一关的核心是“从用户出发，定义真正的价值”。</div><Avatar className="absolute bottom-[-24px] right-28 h-[270px] w-[280px]"/><div className="absolute right-6 top-10 grid size-20 place-items-center rounded-full border-[7px] border-[#d7d3ff] bg-white text-center"><div><b className="text-xl">2/5</b><span className="block text-[9px] text-[#8b91aa]">关卡进度</span></div></div></Card><Card><Title>关卡目标</Title><div className="grid grid-cols-3 gap-3">{[["理解目标用户",UserRound],["提炼真实需求",Search],["输出解决方案",FileText]].map(([x,I])=>{const Icon=I as typeof UserRound;return <div className="flex items-center gap-3 rounded-xl bg-[#fafaff] p-3" key={x as string}><span className="grid size-9 place-items-center rounded-lg bg-[#eeeaff] text-[#6258f5]"><Icon size={17}/></span><div><b className="text-xs">{x as string}</b><p className="text-[9px] text-[#8b91aa]">完成本阶段核心任务</p></div></div>})}</div></Card><div className="grid grid-cols-[260px_1fr_290px] gap-3"><Card><Title>任务清单</Title>{["用户调研与洞察","需求分析与优先级","核心方案设计","方案落地规划","项目复盘输出"].map((x,i)=><button onClick={()=>setTasks(v=>v.map((a,j)=>j===i?!a:a))} className={cx("mb-2 flex w-full items-center gap-2 rounded-xl p-3 text-left text-[10px]",i===2?"bg-[#f0eeff] text-[#6258f5]":"bg-[#fafaff]")} key={x}><span className={cx("grid size-6 place-items-center rounded-lg",tasks[i]?"bg-emerald-100 text-emerald-600":"bg-[#e9eaf3]")}>{tasks[i]?<Check size={12}/>:`0${i+1}`}</span>{x}<Pill green={tasks[i]}>{tasks[i]?"已完成":i===2?"进行中":"待完成"}</Pill></button>)}</Card><Card><Title>项目复盘（提交你的方案）</Title><p className="mb-3 text-[10px] text-[#7e859e]">请对本关任务进行总结与复盘，描述你的方案亮点、思考过程与改进空间。</p><textarea value={text} onChange={e=>setText(e.target.value)} placeholder="我的方案聚焦于解决用户在 AI 写作场景中的内容不精准、效率低问题……" className="h-[250px] w-full resize-none rounded-xl border border-[#e2e4f0] p-4 text-xs outline-none focus:border-[#6258f5]"/><div className="mt-3 flex items-center justify-between"><span className="text-[9px] text-[#8b91aa]">{text.length}/800</span><Button onClick={submit}>提交复盘</Button></div></Card><aside className="space-y-3"><Card><Title>AI 项目评估</Title><div className="text-center"><b className="text-5xl text-emerald-500">{score}</b><span className="ml-2 text-xs text-emerald-600">优秀</span></div>{[["用户洞察力",18],["需求分析力",18],["方案设计力",20],["落地可行性",18],["表达与结构",18]].map(x=><div className="mt-2" key={x[0] as string}><div className="flex justify-between text-[9px]"><span>{x[0]}</span><b>{x[1]}/20</b></div><Progress value={(x[1] as number)*5} green/></div>)}<Button ghost className="mt-4 w-full" onClick={()=>go("review")}>查看详细评估</Button></Card><Card><Title>关卡奖励预览</Title><div className="grid grid-cols-2 gap-2">{["+120 EXP","洞察之眼","方案之星","产品思维卡"].map(x=><div className="rounded-xl bg-[#fafaff] p-3 text-center text-[9px]" key={x}><Award className="mx-auto mb-1 text-amber-500" size={20}/>{x}</div>)}</div></Card></aside></div><Card><Title>成长进度</Title><div className="grid grid-cols-5 gap-2">{["发现用户痛点","需求分析定义","核心方案设计","落地规划执行","项目复盘输出"].map((x,i)=><div className={cx("rounded-xl p-3 text-[10px]",i===2?"border border-[#6258f5] bg-[#f0eeff] text-[#6258f5]":"bg-[#fafaff]")} key={x}>{x}<div className="mt-2"><Progress value={i<2?100:i===2?68:0} green={i<2}/></div></div>)}</div><div className="mt-3 flex justify-end"><Button onClick={()=>setNext(true)}>查看下一关<ChevronRight size={13}/></Button></div>{next&&<p className="mt-3 rounded-xl bg-[#f0eeff] p-3 text-[10px] text-[#6258f5]">下一关：为核心方案设计可执行的 MVP 验证计划。</p>}</Card></div>;
}

