export function SettingsPage({ toast }: { toast:(s:string)=>void }) {
  const categories=[["个人资料",UserRound],["账号信息",Shield],["目标岗位设置",Target],["偏好设置",LayoutGrid],["通知设置",Bell],["隐私设置",Lock],["AI 个性化设置",Sparkles],["数据导出",Download]] as const;
  const [active,setActive]=useState("个人资料");
  const [toggles,setToggles]=useState({notice:true,privacy:true,ai:true,voice:false});
  const toggle=(key:keyof typeof toggles)=>setToggles(v=>({...v,[key]:!v[key]}));
  const content:Record<string,ReactNode>={
    "个人资料":<Card><Title>个人资料</Title><div className="grid grid-cols-[1fr_1.5fr_auto] items-center gap-4"><div className="flex items-center gap-3"><div className="relative size-16 overflow-hidden rounded-full bg-[#e9e7ff]"><Image src="/assets/avatar-student-profile.png" alt="林同学" fill className="object-cover"/></div><div><b>林同学</b><p className="text-[10px] text-[#8b91aa]">Lv.4 成长探索者</p></div></div><div className="grid grid-cols-3 gap-3"><Metric label="性别" value="男"/><Metric label="生日" value="2002-05-20"/><Metric label="学校" value="复旦大学"/></div><Button ghost onClick={()=>toast("资料编辑已打开")}>编辑资料</Button></div></Card>,
    "账号信息":<Card><Title>账号信息</Title>{[["绑定手机号","188****8888"],["绑定邮箱","lintongxue@email.com"],["登录密码","********"],["账号安全等级","高"]].map(x=><button onClick={()=>toast(`修改：${x[0]}`)} className="flex w-full justify-between border-b border-[#f0f1f6] py-4 text-left text-[10px]" key={x[0]}><b>{x[0]}</b><span className="text-[#737b98]">{x[1]}</span><span className="text-[#6258f5]">修改</span></button>)}</Card>,
    "目标岗位设置":<Card><Title>目标岗位设置</Title><div className="grid grid-cols-3 gap-3">{["产品经理","互联网","上海","15K - 25K","全职"].map(x=><button onClick={()=>toast(`调整：${x}`)} className="rounded-xl border border-[#e3e5ef] p-4 text-left text-xs" key={x}>{x}<ChevronRight className="float-right" size={14}/></button>)}</div><Button className="mt-4" onClick={()=>toast("目标岗位已保存")}>保存目标</Button></Card>,
    "偏好设置":<Card><Title>偏好设置</Title><p className="mb-3 text-[10px] text-[#8b91aa]">感兴趣的领域</p><div className="flex flex-wrap gap-2">{["产品设计","用户研究","数据分析","项目管理","运营增长","市场营销"].map(x=><button onClick={()=>toast(`已更新偏好：${x}`)} key={x}><Pill>{x}</Pill></button>)}</div><p className="mb-3 mt-5 text-[10px] text-[#8b91aa]">学习风格</p><div className="flex flex-wrap gap-2">{["视频学习","图文阅读","案例分析","实践练习"].map(x=><button onClick={()=>toast(`已更新学习风格：${x}`)} key={x}><Pill green>{x}</Pill></button>)}</div></Card>,
    "通知设置":<Card><Title>通知设置</Title>{[["系统消息通知","notice"],["副本挑战提醒","notice"],["成长目标提醒","notice"],["推荐试岗推送","notice"]].map(([x,k])=><div className="mb-3 flex justify-between rounded-xl bg-[#fafaff] p-4 text-[10px]" key={x}>{x}<Toggle checked={toggles[k as keyof typeof toggles]} onClick={()=>toggle(k as keyof typeof toggles)}/></div>)}</Card>,
    "隐私设置":<Card><Title>隐私设置</Title>{["个人主页公开","作品集展示","允许他人私信","个性化推荐"].map(x=><div className="mb-3 flex justify-between rounded-xl bg-[#fafaff] p-4 text-[10px]" key={x}>{x}<Toggle checked={toggles.privacy} onClick={()=>toggle("privacy")}/></div>)}</Card>,
    "AI 个性化设置":<Card><Title>AI 个性化设置</Title><div className="grid grid-cols-2 gap-3"><div className="flex justify-between rounded-xl bg-[#fafaff] p-4 text-[10px]">个性化推荐<Toggle checked={toggles.ai} onClick={()=>toggle("ai")}/></div><div className="flex justify-between rounded-xl bg-[#fafaff] p-4 text-[10px]">语音交互<Toggle checked={toggles.voice} onClick={()=>toggle("voice")}/></div></div></Card>,
    "数据导出":<Card><Title>数据导出</Title><div className="grid grid-cols-3 gap-3">{["导出学习数据","导出作品集数据","导出成长报告"].map(x=><Button ghost onClick={()=>toast(x)} key={x}><Download size={12}/>{x}</Button>)}</div></Card>,
  };
  return <div className="space-y-3"><div><h1 className="text-[27px] font-bold">设置</h1><p className="text-xs text-[#7e859e]">管理账号、目标与 AI 个性化偏好</p></div><div className="grid grid-cols-[190px_1fr] items-start gap-3"><Card>{categories.map(([x,I])=>{const Icon=I;return <button onClick={()=>{setActive(x);toast(`已打开：${x}`)}} className={cx("mb-1 flex w-full items-center gap-2 rounded-xl p-3 text-left text-[10px] transition",active===x?"bg-[#f0eeff] font-semibold text-[#6258f5]":"hover:bg-[#fafaff]")} key={x}><Icon size={14}/>{x}</button>})}</Card><div className="space-y-3">{content[active]}<Card className="flex items-center justify-between"><span className="text-[10px] text-[#8b91aa]">当前设置会自动保存在演示状态中</span><Button ghost onClick={()=>toast("设置已保存")}>保存设置</Button></Card></div></div></div>;
}

export function V2App() {
  const [page,setPage]=useState<PageId>("dashboard"); const [growth,setGrowth]=useState(120); const [message,setMessage]=useState(""); const [map,setMap]=useState(false);
  const toast=(s:string)=>{setMessage(s);window.setTimeout(()=>setMessage(""),2200)};
  const go=(p:PageId)=>setPage(p);
  const pages:Record<PageId,ReactNode>={
    dashboard:<Dashboard go={go}/>,avatar:<AvatarPage go={go}/>,recommend:<Recommend go={go}/>,
    skill:<SkillPage go={go} toast={toast}/>,mission:<Mission go={go} grow={()=>setGrowth(x=>x+120)} toast={toast}/>,
    review:<Review go={go}/>,portfolio:<Portfolio toast={toast}/>,learning:<Learning toast={toast}/>,
    resume:<Resume toast={toast}/>,interview:<Interview toast={toast}/>,settings:<SettingsPage toast={toast}/>,
  };
  return <div className="min-h-screen bg-[#f7f8fc] text-[#171a2d]"><Sidebar page={page} go={go}/><Topbar growth={growth} map={()=>setMap(true)}/><motion.main key={page} initial={{opacity:0,y:8}} animate={{opacity:1,y:0}} transition={{duration:.22}} className="ml-[240px] min-h-screen pt-[66px]"><div className="mx-auto max-w-[1680px] p-4">{pages[page]}</div></motion.main><AnimatePresence>{message&&<motion.div initial={{opacity:0,y:12}} animate={{opacity:1,y:0}} exit={{opacity:0,y:12}} className="fixed bottom-6 right-6 z-50 flex items-center gap-2 rounded-xl bg-[#171a2d] px-4 py-3 text-xs text-white shadow-2xl"><Check size={14} className="text-emerald-400"/>{message}</motion.div>}</AnimatePresence><AnimatePresence>{map&&<motion.div initial={{opacity:0}} animate={{opacity:1}} exit={{opacity:0}} className="fixed inset-0 z-50 grid place-items-center bg-[#171a2d]/40 backdrop-blur-sm" onClick={()=>setMap(false)}><motion.div initial={{scale:.96,y:15}} animate={{scale:1,y:0}} onClick={e=>e.stopPropagation()} className="w-[720px] rounded-2xl bg-white p-6"><div className="flex justify-between"><h2 className="text-lg font-bold">我的成长地图</h2><button onClick={()=>setMap(false)}><X/></button></div><div className="mt-6 grid grid-cols-5 gap-3">{["自我探索","能力筑基","项目实践","求职冲刺","职场进阶"].map((x,i)=><button onClick={()=>toast(`已查看：${x}`)} className={cx("rounded-xl border p-4 text-center text-[10px]",i===2?"border-[#6258f5] bg-[#f0eeff]":"border-[#e8e9f3]")} key={x}><span className={cx("mx-auto grid size-8 place-items-center rounded-full",i<3?"bg-[#6258f5] text-white":"bg-[#eceef5]")}>{i<2?<Check size={13}/>:i+1}</span><b className="mt-3 block">{x}</b></button>)}</div></motion.div></motion.div>}</AnimatePresence></div>;
}
